// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

const item = $input.first().json;
const clientes = item.body.clientes;

// Lista de produtos de investimento por perfil
const investimentos = [
  { perfil: "Conservador", produto: "CDB Liquidez Diária",   minimo: 1000, rentabilidade: 12.5 },
  { perfil: "Conservador", produto: "Tesouro Selic",          minimo: 100,  rentabilidade: 11.8 },
  { perfil: "Conservador", produto: "LCI/LCA",                minimo: 5000, rentabilidade: 13.0 },
  { perfil: "Moderado",    produto: "Fundos Multimercado",    minimo: 1000, rentabilidade: 15.0 },
  { perfil: "Moderado",    produto: "Debêntures",             minimo: 1000, rentabilidade: 14.5 },
  { perfil: "Moderado",    produto: "FIIs",                   minimo: 500,  rentabilidade: 13.8 },
  { perfil: "Arrojado",    produto: "Ações na Bolsa",         minimo: 500,  rentabilidade: 20.0 },
  { perfil: "Arrojado",    produto: "ETFs",                   minimo: 100,  rentabilidade: 18.5 },
  { perfil: "Arrojado",    produto: "Criptomoedas",           minimo: 50,   rentabilidade: 30.0 },
];

// Função para escolher mensagem aleatória
function pick(arr) {
  return arr[Math.floor(Math.random() * arr.length)];
}

const resultados = clientes.map(cliente => {
  const saldoNum = parseFloat(
    cliente.saldo.replace("R$", "").replace(/\./g, "").replace(",", ".").trim()
  );

  // Pega o primeiro produto compatível com o perfil
  const inv = investimentos.find(i => i.perfil === cliente.perfil) || {
    produto: "Consultar assessor", minimo: 0, rentabilidade: 0
  };

  const motivo = saldoNum >= inv.minimo ? "saldo_ok" : "saldo_insuficiente";

  const mensagens = [
    `Olá ${cliente.nome}! Pelo seu perfil (${cliente.perfil}), uma boa opção é **${inv.produto}** (mínimo R$ ${inv.minimo.toLocaleString('pt-BR')},00). Com seu saldo atual (R$ ${saldoNum.toLocaleString('pt-BR')},00), você já consegue investir. Rentabilidade: ${inv.rentabilidade}%.`,
    `Oi ${cliente.nome}! Recomendação para perfil ${cliente.perfil}: **${inv.produto}** (mínimo R$ ${inv.minimo.toLocaleString('pt-BR')},00). Seu saldo (R$ ${saldoNum.toLocaleString('pt-BR')},00) já atende o mínimo. Rentabilidade: ${inv.rentabilidade}%.`,
    `${cliente.nome}, indo direto ao ponto: para o perfil ${cliente.perfil}, **${inv.produto}** (mínimo R$ ${inv.minimo.toLocaleString('pt-BR')},00). Você tem R$ ${saldoNum.toLocaleString('pt-BR')},00, então dá pra aplicar. Rentabilidade: ${inv.rentabilidade}%.`
  ];

  return {
    nome: cliente.nome,
    email: cliente.email,
    perfil: cliente.perfil,
    saldo_texto: cliente.saldo,
    saldo_num: saldoNum,
    recomendacao: {
      perfil: cliente.perfil,
      produto: inv.produto,
      minimo: inv.minimo,
      rentabilidade: `${inv.rentabilidade}%`
    },
    motivo: motivo,
    mensagens: mensagens,
    mensagem_escolhida: pick(mensagens)
  };
});

return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
    resultados: resultados
  }
}];

const resultados = $json.resultados || [];

function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// retorna UM ITEM por cliente
const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);
  return {
    json: {
      ...c,
      saldo_num: saldoNum,
    }
  };
});

return out;

