const respostas = $input.all();
const clientes = $('Code in JavaScript2').all();

return respostas.map((item, index) => {
  const cliente = clientes[index]?.json ?? {};

  const texto =
    item.json.content?.parts
      ?.find(part => part.text)
      ?.text ?? '';

  return {
    json: {
      to: cliente.email ?? '',
      subject: `Recomendação de investimento - ${cliente.nome ?? 'Cliente'}`,
      textBody: texto,
    }
  };
});
